{
  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be dict')
    for key in ('items', 'required_failure_items', 'unresolved_without'):
        if key not in case:
            raise ValueError(f'Missing key {key}')
    items = case['items']
    req_fail = case['required_failure_items']
    unres = case['unresolved_without']
    if not isinstance(items, list) or not isinstance(req_fail, list) or not isinstance(unres, list):
        raise ValueError('fields must be lists')

    config = list(items)
    test_count = 0

    def outcome(subset):
        nonlocal test_count
        test_count += 1
        s = set(subset)
        for u in unres:
            if u not in s:
                return 'UNRESOLVED'
        for r in req_fail:
            if r not in s:
                return 'PASS'
        return 'FAIL'

    if outcome(config) != 'FAIL':
        raise ValueError('initial configuration must FAIL')

    n = 2
    while True:
        L = len(config)
        if n > L:
            n = L
        size = L // n
        rem = L % n
        subsets = []
        start = 0
        for i in range(n):
            sz = size + (1 if i < rem else 0)
            subsets.append(config[start:start+sz])
            start += sz

        found = False
        # test subsets
        for sub in subsets:
            if len(sub) == 0:
                continue
            res = outcome(sub)
            if res == 'FAIL' and len(sub) < L:
                config = sub
                n = 2
                found = True
                break
        if found:
            continue

        # test complements
        for sub in subsets:
            if len(sub) == 0:
                continue
            comp = [x for x in config if x not in set(sub)]
            if len(comp) == 0:
                continue
            res = outcome(comp)
            if res == 'FAIL' and len(comp) < L:
                config = comp
                n = 2
                found = True
                break
        if found:
            continue

        if n < L:
            n = min(2 * n, L)
        else:
            break

    return {
        'outcome': 'FAIL',
        'tests': test_count,
        'minimal_failure': config
    }"
}
